$root='C:\Users\Elior\AppData\Local\Temp\FutureClassroom-Test-TLS-6461b9b6bc9e4a998754002cd064a288';$marker='FutureClassroom-Test-TLS-6461b9b6bc9e4a998754002cd064a288'
